// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(bool payRoyalties, uint128 virtualBase, uint128 virtualNft, uint56 changeFee, uint16 feeRate) public {
        if (feeRate > 5000) feeRate = 5000;

        bool ok;
        try c.initialize(address(0), address(0), virtualBase, virtualNft, changeFee, feeRate, bytes32(0), false, payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.payRoyalties() == payRoyalties);
        } else {
            assertTrue(ok == false || c.payRoyalties() == payRoyalties);
        }
    }
}
